# AT&T-syntax twin of examples/TESTCPU-0.asm (E3.T1): the same program,
# and ctest requires the same output in every format. Generated by
# scripts/to_att.py; see that file for what it does and why.

.ORG 0x0000

AAA # 0 operands

AAB %R0 # 1 operand, mode 1 (reg)
AAC (%R1) # 1 operand, mode 2 (regindex)
AAD $0x0005 # 1 operand, mode 3 (immediate)
AAE 0x0010 # 1 operand, mode 4 (direct)
AAF 0x0004(%R2) # 1 operand, mode 5 (indexed)
.BYTE 0x1A, 0x83, 0x00, 0x04 # no AT&T spelling for: AAG [[R3 + 0x0004]]
AAH 0x0004(%RIP) # 1 operand, mode 7 (relative)
.BYTE 0x23, 0x80, 0x00, 0x04 # no AT&T spelling for: AAI [[PC + 0x0004]]

AAJ %R1, %R0 # 2 operands, load, mode 1 (reg)
AAK (%R1), %R0 # 2 operands, load, mode 2 (regindex)
AAL $0x0005, %R0 # 2 operands, load, mode 3 (immediate)
AAM 0x0010, %R0 # 2 operands, load, mode 4 (direct)
AAN 0x0004(%R2), %R0 # 2 operands, load, mode 5 (indexed)
.BYTE 0x3A, 0x98, 0x00, 0x04 # no AT&T spelling for: AAO R0, [[R3 + 0x0004]]
AAP 0x0004(%RIP), %R0 # 2 operands, load, mode 7 (relative)
.BYTE 0x43, 0x80, 0x00, 0x04 # no AT&T spelling for: AAQ R0, [[PC + 0x0004]]

AAR %R0, %R1 # 2 operands, store, mode 1 (reg)
AAS %R0, (%R1) # 2 operands, store, mode 2 (regindex)
AAT %R0, 0x0010 # 2 operands, store, mode 4 (direct)
AAU %R0, 0x0004(%R2) # 2 operands, store, mode 5 (indexed)
.BYTE 0x56, 0xC3, 0x00, 0x04 # no AT&T spelling for: AAV [[R3 + 0x0004]], R0
AAW %R0, 0x0004(%RIP) # 2 operands, store, mode 7 (relative)
.BYTE 0x5F, 0xC0, 0x00, 0x04 # no AT&T spelling for: AAX [[PC + 0x0004]], R0

AAY %R3, %R2, %R1 # 3 operands, all registers


start: # a bare label, for .GLOBAL to mark below
.GLOBAL start # marks "start" visible outside this file;

AAD_WIDTH .EQU 0x0005 # defines a reusable named constant

AAD $AAD_WIDTH # same AAD (mode 3, immediate) rule as above, operand is the

BIG64 .EQU 0xFFFFFFFFFFFFFFFF # exercises the full 64-bit width end-to-end

MyBytes: .BYTE 0x01, 0x02, 0x03 # a literal byte list
MyAscii: .ASCII "done\n" # a raw string, no auto-terminator
MyAsciz: .ASCIZ "done" # like .ASCII, but auto-terminated with a trailing \0
MyWord:  .WORD 0x0102, 0x0304 # 16-bit values, little-endian
MyLong:  .LONG 0x01020304 # 32-bit values, little-endian (.INT is an accepted alias)
MyQuad:  .QUAD 0x0102030405060708 # 64-bit values, little-endian

.EXTERN SomeOtherFilesFunction # records a symbol expected to be defined elsewhere;

.ALIGN 4 # pads with 0x00 until the address is a multiple of 4
MyAligned: .BYTE 0xAA # lands on a 4-byte boundary because of the .ALIGN above

AAD_SPAN .EQU MyAligned - MyBytes # 0x1F: .EQU may use labels already defined
AAD $AAD_WIDTH + AAD_SPAN - 1 # 0x23
AAL $MyAligned - MyBytes + 1, %R1 # the same difference, inline

COUNT .SET 1
AAD $COUNT # 1
COUNT .SET COUNT + 1
AAD $COUNT # 2

.SPACE 3 # three zero bytes
Utf8: .ASCIZ "héllo, wörld ✓" # UTF-8 in a string keeps its bytes (and in a comment: π ≈ 3.14)

AAZ 4(%R1, %R2, 2)

.ORG 0x0200

AAA
AAB %R1
Tail: .ASCIZ "end"
